SELECT ?p ?class WHERE {
  ?p a brick:Zone .
  ?p brick:hasSubClass* ?p .
  ?p rdfs:label ?class
}

SELECT ?zone ?label ?sensor ?class WHERE {
  ?point a ?class .
  ?point brick:isPointOf ?zone .
  ?zone rdfs:label ?label .
  FILTER(str(?label) LIKE "Core%")
}

SELECT ?point ?class ?tsref WHERE {
  ?point a ?class .
  ?point brick:isPointOf ?z .
  ?z a ?zt .
  OPTIONAL { ?point brick:ref:hasExternalReference ?ref . ?ref brick:ref:hasTimeseriesId ?tsref }
  FILTER(str(?zt) LIKE "%Zone%" && (str(?class) LIKE "%Air_Temperature%" || str(?class) LIKE "%Damper%" || str(?class) LIKE "%Flow%"))
}

